VALUES (gen_random_uuid()::text, $q$chatfam-3d-family-chat$q$, $q$Chatfam: 3D Family Chat App$q$, $q$A visual interactive app with 3D family members (brother, sister and so on), room customization, login and a chat system powered by OpenAI. It is live on the App Store and Play Store.$q$, $q$Simulation$q$, ARRAY[$q$Mobile App$q$, $q$3D$q$, $q$AI Chat$q$, $q$Social$q$, $q$Unity$q$]::text[], $q$Unity, C#, Python, OpenAI, AWS, PlayFab$q$, NULL, $q$👨‍👩‍👧$q$, $q$#7e22ce$q$, true, 4, $q$GAME$q$, $q$COMPANY$q$, $q$Full project developer working directly with the client$q$, $q$Over 3 to 4 months I worked directly with the client, with my CEO and manager alongside me. I handled development, production and release for both the Unity frontend and the Python backend.$q$, ARRAY[$q$3D family characters and relationship system$q$, $q$Room customization$q$, $q$Login and authentication$q$, $q$AI chat system connected to OpenAI through a Python backend$q$, $q$Backend hosted on AWS$q$, $q$Player data management with PlayFab$q$, $q$Release to both app stores$q$]::text[], ARRAY[$q$Me$q$, $q$My CEO and manager$q$, $q$The client$q$]::text[], $q$Live on the App Store and Play Store.$q$, ARRAY[$q$3D family relationship characters$q$, $q$Room customization$q$, $q$Account login$q$, $q$AI powered chat$q$, $q$Cloud saved data$q$]::text[], ARRAY[$q$Python backend that connects the app to OpenAI$q$, $q$AWS hosting$q$, $q$PlayFab for data and player management$q$, $q$Direct client communication through the whole production cycle$q$]::text[], $q$Android and iOS$q$, $q$https://apps.apple.com/us/app/chatfam-your-ai-family/id6755918394$q$, false, CURRENT_TIMESTAMP)
