VALUES (gen_random_uuid()::text, $q$mass-transit-system-simulation$q$, $q$Mass Transit System$q$, $q$A world mass transit simulation built from Kaggle datasets. It calculates distances, fares and travel times between locations with Dijkstra's, Kruskal's and Prim's algorithms, plus custom algorithms that use the dataset to find shortest paths efficiently in both directions.$q$, $q$Algorithms$q$, ARRAY[$q$C++$q$, $q$Graph Algorithms$q$, $q$Shortest Path$q$, $q$Simulation$q$, $q$Data Structures$q$]::text[], $q$C++, Visual Studio, Dijkstra, Kruskal, Prim$q$, $q$2023$q$, $q$🚇$q$, $q$#1e3a8a$q$, true, 18, $q$OTHER$q$, $q$ACADEMIC$q$, NULL, $q$Semester project for Data Structures and Algorithms.$q$, ARRAY[]::text[], ARRAY[]::text[], NULL, ARRAY[$q$Distance, fare and time calculation between locations$q$, $q$Shortest paths in both directions$q$]::text[], ARRAY[]::text[], NULL, NULL, false, CURRENT_TIMESTAMP)
